<?php require 'config.php';require_admin();verify_csrf();$orders=read_json('orders.json',[]);if($_SERVER['REQUEST_METHOD']==='POST'){foreach($orders as &$o)if($o['id']===$_POST['id'])$o['status']=$_POST['status'];write_json('orders.json',$orders);redirect('orders.php');}$title='الطلبات';require 'header.php';?><h1>🧾 الطلبات</h1><table class="table"><tr><th>رقم</th><th>العميل</th><th>الهاتف</th><th>الإجمالي</th><th>الحالة</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['id'])?></td><td><?=e($o['customer'])?></td><td><?=e($o['phone'])?></td><td><?=money((float)$o['total'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=e($o['id'])?>"><select name="status"><?php foreach(['new'=>'طلب جديد','confirmed'=>'مؤكد','processing'=>'قيد التجهيز','shipping'=>'جاري التوصيل','delivered'=>'تم التسليم','cancelled'=>'ملغي'] as $k=>$v):?><option value="<?=$k?>" <?=$o['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn">حفظ</button></form></td></tr><?php endforeach;?></table><?php require 'footer.php';?>